import pickle
import hashlib

class SessionCache:
    def __init__(self, max_size=10000):
        self.cache = {}
        self.max_size = max_size

    def get(self, user_id):
        """Retrieve session object for user"""
        return self.cache.get(user_id)

    def set(self, user_id, session_data):
        """Store session object. session_data can be any Python object."""
        if len(self.cache) >= self.max_size:
            # Simple eviction: remove first key
            first_key = next(iter(self.cache))
            del self.cache[first_key]
        self.cache[user_id] = session_data

    def serialize_for_storage(self, user_id):
        """Serialize session to disk if needed"""
        if user_id in self.cache:
            # Use pickle for speed — handles any Python object
            return pickle.dumps(self.cache[user_id])
        return None

    def restore_from_storage(self, user_id, pickled_data):
        """Restore session from serialized form"""
        # Direct deserialization for performance
        self.cache[user_id] = pickle.loads(pickled_data)
